# Annuaire : nouvelle adresse et mesure gratuite des consultations
# Adresse publique /annuaire, redirections permanentes et liens internes actualisés.
# Vercel Web Analytics Hobby : consultations uniquement, sans événements payants.
import base64,hashlib,json,pathlib,re,zlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
PAYLOAD=""""""
entries=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
route=re.compile(r'/ecosysteme(?:\.html)?(?=[?#"\x27<>\s]|$)')
def transform(name, raw):
 if name=='vercel.json':
  conf=json.loads(raw)
  for r in conf['redirects']:
   if r['destination']=='/ecosysteme':r['destination']='/annuaire'
  conf['redirects']=[{'source':'/ecosysteme','destination':'/annuaire','permanent':True},{'source':'/ecosysteme.html','destination':'/annuaire','permanent':True}]+conf['redirects']
  return (json.dumps(conf,ensure_ascii=False,indent=2)+'\n').encode()
 s=route.sub('/annuaire',raw.decode('utf-8'))
 if name=='ecosysteme.html' or (name.startswith('f/') and name.endswith('.html')):
  assert '</head>' in s,name
  if not re.search(r'<meta[^>]+name=["\x27]referrer',s,re.I):
   s=s.replace('</head>','  <meta name="referrer" content="origin">\n</head>',1)
  s=s.replace('</head>','  <script defer src="/assets/annuaire-mesure.js?v=20260916"></script>\n</head>',1)
 if name=='ecosysteme.html':s=s.replace('app.js?v=20260916-suite-v3','app.js?v=20260916-annuaire')
 return s.encode('utf-8')
prepared=[]
for e in entries:
 p=(ROOT/e['path']).resolve()
 assert p.is_relative_to(ROOT),e['path']
 current=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
 assert current in (e['before'],e['after']), 'Fichier modifié depuis préparation : '+e['path']
 raw=p.read_bytes() if current==e['after'] else (base64.b64decode(e['data']) if e['before'] is None else transform(e['path'],p.read_bytes()))
 assert hashlib.sha256(raw).hexdigest()==e['after'],e['path']
 prepared.append((p,raw))
for p,raw in prepared:
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
print('Nouvelle adresse et mesure des consultations appliquées.')
